command:
$ErrorActionPreference = 'Stop'
$workspaceRoot = 'D:\GitHub\Forge-Conductor-Windows-Edition'
. (Join-Path $workspaceRoot '.forge-codex\instructions\scripts\Common.ps1')
$evidenceRelative = '.forge-codex\state\evidence\P16\manager-unavailable-telemetry-checkpoint.json'
$evidencePath = Join-Path $workspaceRoot $evidenceRelative
$evidence = Get-Content -Raw -LiteralPath $evidencePath | ConvertFrom-Json
$sourceProperties = @($evidence.source_sha256.PSObject.Properties)
if ($sourceProperties.Count -ne 8) { throw "Unexpected source hash count: $($sourceProperties.Count)" }
foreach ($property in $sourceProperties) {
    $actual = Get-FileSha256 -Path (Join-Path $workspaceRoot $property.Name)
    if ($actual -ne [string]$property.Value) { throw "Source hash mismatch: $($property.Name)" }
}
$binaryPaths = [ordered]@{
    'ForgeConductor.Manager.UnavailableTelemetryServiceTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Manager.UnavailableTelemetryServiceTests.exe'
    'ForgeConductor.Dashboard.ConnectionApplicationTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Dashboard.ConnectionApplicationTests.exe'
    'ForgeConductor.Dashboard.TelemetrySourceTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Dashboard.TelemetrySourceTests.exe'
    'ForgeConductor.Manager.Composition.Windows.lib' = 'out\build\windows-msvc-x64\lib\Release\ForgeConductor.Manager.Composition.Windows.lib'
    'ForgeConductor.Application.lib' = 'out\build\windows-msvc-x64\lib\Release\ForgeConductor.Application.lib'
}
if (@($evidence.binary_sha256.PSObject.Properties).Count -ne $binaryPaths.Count) { throw 'Unexpected binary hash count.' }
foreach ($entry in $binaryPaths.GetEnumerator()) {
    $actual = Get-FileSha256 -Path (Join-Path $workspaceRoot $entry.Value)
    if ($actual -ne [string]$evidence.binary_sha256.($entry.Key)) { throw "Binary hash mismatch: $($entry.Key)" }
}
$commandRecords = @(
    [pscustomobject]@{ Relative = [string]$evidence.recorded_build.command_record; Expected = [string]$evidence.recorded_build.command_record_sha256; StdoutExpected = [string]$evidence.recorded_build.stdout_sha256; StderrExpected = [string]$evidence.recorded_build.stderr_sha256 },
    [pscustomobject]@{ Relative = [string]$evidence.recorded_validation.command_record; Expected = [string]$evidence.recorded_validation.command_record_sha256; StdoutExpected = [string]$evidence.recorded_validation.stdout_sha256; StderrExpected = [string]$evidence.recorded_validation.stderr_sha256 }
)
$loadedRecords = @()
foreach ($record in $commandRecords) {
    $recordPath = Join-Path $workspaceRoot $record.Relative
    if ((Get-FileSha256 -Path $recordPath) -ne $record.Expected) { throw "Command-record hash mismatch: $($record.Relative)" }
    $loaded = Get-Content -Raw -LiteralPath $recordPath | ConvertFrom-Json
    if ($loaded.exit_code -ne 0 -or $loaded.timed_out -or $loaded.output_limit_exceeded -or $loaded.stdout_truncated -or $loaded.stderr_truncated) { throw "Recorded command did not pass intact: $($record.Relative)" }
    if ((Get-FileSha256 -Path (Join-Path $workspaceRoot $loaded.stdout)) -ne $record.StdoutExpected) { throw "stdout hash mismatch: $($record.Relative)" }
    if ((Get-FileSha256 -Path (Join-Path $workspaceRoot $loaded.stderr)) -ne $record.StderrExpected) { throw "stderr hash mismatch: $($record.Relative)" }
    $loadedRecords += $loaded
}
$buildRecord = $loadedRecords[0]
$testRecord = $loadedRecords[1]
if ([string]$buildRecord.command -match '(-L|--label-regex)\s+G16') { throw 'Focused build invoked the G16 label gate.' }
if ([string]$testRecord.command -match '(-L|--label-regex)\s+G16') { throw 'Focused validation invoked the G16 label gate.' }
$expectedSelection = '^(ForgeConductor\.Manager\.UnavailableTelemetryServiceTests|ForgeConductor\.Dashboard\.ConnectionApplicationTests|ForgeConductor\.Dashboard\.TelemetrySourceTests)$'
if (-not ([string]$testRecord.command).Contains($expectedSelection)) { throw 'Focused validation selection is not the exact anchored three-test regex.' }
$testStdout = Get-Content -Raw -LiteralPath (Join-Path $workspaceRoot $testRecord.stdout)
if ($testStdout -notmatch '100% tests passed out of 3') { throw 'Focused validation did not report three passing tests.' }
$runState = Get-Content -Raw -LiteralPath (Join-Path $workspaceRoot '.forge-codex\state\run-state.json') | ConvertFrom-Json
$p16 = @($runState.phases | Where-Object id -eq 'P16')
$g16 = @($runState.gates | Where-Object id -eq 'G16')
if ($p16.Count -ne 1 -or $p16[0].status -ne 'in_progress') { throw 'P16 durable state is not in_progress.' }
if ($g16.Count -ne 1 -or $g16[0].status -ne 'not_started' -or @($g16[0].evidence).Count -ne 0) { throw 'G16 durable state is not untouched.' }
$requiredP16Evidence = @(
    '.forge-codex/state/decisions/P16-030-truthful-unavailable-telemetry-and-manager-reachability.md',
    '.forge-codex/state/evidence/P16/manager-unavailable-telemetry-checkpoint.json',
    '.forge-codex/state/commands/20260830T132722732Z-804fd72a.json',
    '.forge-codex/state/commands/20260830T132739991Z-483abbd8.json'
)
foreach ($required in $requiredP16Evidence) {
    if ($p16[0].evidence -notcontains $required) { throw "P16 durable state omits $required" }
}
& (Join-Path $workspaceRoot '.forge-codex\instructions\scripts\Validate-NoPython.ps1') -WorkspaceRoot $workspaceRoot
& (Join-Path $workspaceRoot '.forge-codex\instructions\scripts\Validate-NoAttribution.ps1') -WorkspaceRoot $workspaceRoot
& (Join-Path $workspaceRoot '.forge-codex\instructions\scripts\Verify-Ledger.ps1') -WorkspaceRoot $workspaceRoot
$priorErrorAction = $ErrorActionPreference
$ErrorActionPreference = 'Continue'
$diffOutput = & git -c core.safecrlf=false -C $workspaceRoot diff --check 2>&1
$diffExitCode = $LASTEXITCODE
$ErrorActionPreference = $priorErrorAction
if ($diffExitCode -ne 0) { throw "git diff --check failed: $diffOutput" }
$changedTextFiles = @($sourceProperties.Name) + $evidenceRelative
$strictUtf8 = New-Object Text.UTF8Encoding($false, $true)
foreach ($relative in $changedTextFiles) {
    $bytes = [IO.File]::ReadAllBytes((Join-Path $workspaceRoot $relative))
    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xef -and $bytes[1] -eq 0xbb -and $bytes[2] -eq 0xbf) { throw "UTF-8 BOM is forbidden: $relative" }
    $text = $strictUtf8.GetString($bytes)
    if ($text -match '(?<!\r)\n' -or $text -match '\r(?!\n)') { throw "Non-CRLF line ending: $relative" }
    foreach ($line in [regex]::Split($text, '\r\n')) { if ($line -match '[ \t]+$') { throw "Trailing whitespace: $relative" } }
}
Write-Output "Source hashes matched: $($sourceProperties.Count)"
Write-Output "Binary hashes matched: $($binaryPaths.Count)"
Write-Output "Command records matched: $($commandRecords.Count)"
Write-Output "Changed text files CRLF UTF-8 no BOM: $($changedTextFiles.Count)"
Write-Output 'Exact focused selection did not invoke the G16 label gate.'
Write-Output 'P16 in_progress and untouched G16 durable state verified.'
Write-Output 'No-Python, no-attribution, ledger, and git diff checks passed.'
exit 0
